//! UsedFilaments failure inventory: both remaining-volume split branches,
//! repeated virtual flush, inactive/zero E, physical flush sharing the same
//! remainder, and exactly one authoritative set of five accumulated maps.
use std::process::Command;

pub(super) fn check(project: &[u8]) {
    let processed = super::state_oracle::processed(project);
    let text = std::str::from_utf8(&processed.gcode).unwrap();
    let renamed = text.replacen(
        "; generated by Ares 2.4.2",
        "; generated by OrcaSlicer 2.4.2",
        1,
    );
    assert_ne!(text, renamed);
    let directory = tempfile::Builder::new()
        .prefix("vg1-volumes-oracle-")
        .tempdir()
        .unwrap()
        .keep();
    let input = directory.join("input.gcode");
    let dump = directory.join("native.json");
    std::fs::write(&input, renamed).unwrap();
    let run = Command::new(std::env::var_os("ARES_PROCGCODE_BIN").unwrap())
        .arg("--process-gcode")
        .arg(&input)
        .arg("--dump-color-change")
        .arg(&dump)
        .output()
        .unwrap();
    std::fs::write(
        directory.join("native.log"),
        [&run.stdout[..], &run.stderr[..]].concat(),
    )
    .unwrap();
    assert!(run.status.success(), "{:?}; {directory:?}", run.status);
    let native: serde_json::Value = serde_json::from_slice(&std::fs::read(dump).unwrap()).unwrap();
    let actual = &processed.result.print_statistics;
    std::fs::write(
        directory.join("ares-statistics.txt"),
        format!("{actual:#?}"),
    )
    .unwrap();
    let count = native["filament_diameters"].as_array().unwrap().len();
    for (name, actual) in [
        ("flush_per_filament", &actual.flush_per_filament),
        (
            "total_volumes_per_extruder",
            &actual.total_volumes_per_extruder,
        ),
        (
            "model_volumes_per_extruder",
            &actual.model_volumes_per_extruder,
        ),
        (
            "support_volumes_per_extruder",
            &actual.support_volumes_per_extruder,
        ),
        (
            "wipe_tower_volumes_per_extruder",
            &actual.wipe_tower_volumes_per_extruder,
        ),
    ] {
        // The public Rust result uses a dense vector; Native std::map
        // serializes as id/value pairs and omits keys with no contribution.
        let mut expected = vec![0.0_f64; count];
        for entry in native[name].as_array().unwrap() {
            expected[entry[0].as_u64().unwrap() as usize] = entry[1].as_f64().unwrap();
        }
        assert_eq!(actual.len(), count, "{name}; {directory:?}");
        for (id, (actual, expected)) in actual.iter().zip(expected).enumerate() {
            assert_eq!(
                actual.to_bits(),
                expected.to_bits(),
                "{name}[{id}]; {directory:?}"
            );
        }
    }
}
